/* Tenants report; agencies and owner-landlords authorise and dispatch. */
function clientOwner(){return agencyNow()?.accountType==='landlord'?'landlord':'property manager'}
const normaliseBeforeAuthority=normalise;normalise=function(){normaliseBeforeAuthority();for(const j of state.jobs){if(j.status==='Awaiting client review')j.status='Awaiting property manager review';if(j.dispatchStatus==='Awaiting client review')j.dispatchStatus='Awaiting property manager review'}for(const a of state.agencies)a.accountType??='agency';if(!state.authorityDemoVersion){const landlord={id:'demo-landlord-workspace',name:'Demo Landlord · Own Properties',contact:'Jordan · demo owner',email:'landlord@example.com',phone:'082 555 0170',area:'Gauteng',accountType:'landlord'};if(!state.agencies.some(a=>a.id===landlord.id)){state.agencies.push(landlord);state.properties.push({id:'demo-landlord-property',agency:landlord.id,name:'Demo owner property · Unit 1',address:'1 Example Street, Meyerton',landlord:'Jordan · demo owner'});state.tenants.push({id:'demo-landlord-tenant',agency:landlord.id,property:'demo-landlord-property',name:'Demo tenant · Lee',email:'lee@example.com',phone:'083 555 0180'})}for(const [aid,pid,tid,ref] of [['a1','p1','t1','DEMO-REVIEW'],[landlord.id,'demo-landlord-property','demo-landlord-tenant','DEMO-OWNER-REVIEW']]){if(state.agencies.some(a=>a.id===aid)&&state.properties.some(p=>p.id===pid)&&!state.jobs.some(j=>j.ref===ref))state.jobs.push(makeTenantReport({agency:aid,property:pid,tenant:tid,category:'Plumbing',title:'Demo: tap leaking',description:'Example tenant report for review before sending to Sevlink.',photo:null,ref}))}state.authorityDemoVersion=1}};
function makeTenantReport({agency:aid,property:pid,tenant:tid,category,title,description,photo,ref}){const created=now();if(photo){photo.phase='before';photo.at=created}return {id:id('j'),ref:ref||'SV-'+(1040+state.jobs.length),agency:aid,property:pid,tenant:tid,category,title,description,priority:'Not set',status:'Awaiting property manager review',dispatchStatus:'Awaiting property manager review',sentToSevlink:false,submittedBy:'tenant',tenantReport:{title,description,submittedAt:created},team:'Unassigned',assigned:false,photos:photo?[photo]:[],beforePhotos:photo?[photo]:[],afterPhotos:[],comments:[],quotes:[],invoices:[],schedule:null,events:[],createdAt:created,history:['Tenant reported issue to property manager'],reviewedAt:null,opsAction:null,callout:null,access:{status:'Awaiting tenant',note:''}}}
const visibleBeforeAuthority=visibleJobs;visibleJobs=function(){return visibleBeforeAuthority().filter(j=>role!=='sevlink'||j.sentToSevlink!==false)};
const enrichBeforeAuthority=enrichChanges;enrichChanges=function(before){enrichBeforeAuthority(before);for(const j of state.jobs.filter(j=>j.sentToSevlink===false)){const old=before.jobs.find(x=>x.id===j.id);if(!old){addEvent(j,'Sent for property review','Report received by the property agency. It has not been sent to Sevlink.');for(const m of state.messages.filter(m=>m.job===j.id)){m.type='Tenant report for client review';m.text=j.ref+': a tenant reported a problem. Review it before sending to Sevlink.'}}}};
const reportBeforeAuthority=reportForm;reportForm=function(category='Plumbing'){if(role!=='tenant')return reportBeforeAuthority(category);const t=state.tenants.find(t=>t.id===tenant&&t.agency===agency),p=t&&property(t.property);if(!t||!p){toast('Your account needs to be linked to a property before reporting an issue.');return}const g=guide[category]||guide.Plumbing;openForm('Report a problem.',`<div class="notice"><b>${esc(p.name)}</b><br>Your report goes to your ${clientOwner()} for review.</div><label>What is the problem?</label><select name="issue">${g.issues.map(i=>`<option>${i}</option>`).join('')}</select><label>Tell us what happened</label><textarea name="description" required rows="4" maxlength="2500" placeholder="Where is the issue, when did it start, and what can you see?"></textarea><label>Photo (optional, up to 5 MB)</label><input name="photo" type="file" accept="image/jpeg,image/png,image/webp"><div class="notice">Your ${clientOwner()} will decide the next action and arrange any work. For immediate danger, use your property's established emergency contact.</div>`,'Send report to '+clientOwner(),async d=>{let photo;try{photo=await fileData(d.get('photo'),imageTypes)}catch(e){toast(e.message);return}if(await submitTenantReport({property:p.id,category,title:d.get('issue'),description:d.get('description'),photo})){modal.close();navigate('requests');toast('Report sent for property review.')}})};
async function submitTenantReport({property:pid,category,title,description,photo}){const t=state.tenants.find(t=>t.id===tenant&&t.agency===agency);if(role!=='tenant'||!t||t.property!==pid||!title?.trim()||!description?.trim())return false;return commit(()=>state.jobs.unshift(makeTenantReport({agency,property:pid,tenant,category,title,description,photo})))}
function tenantReviewJobs(){return role==='manager'?visibleJobs().filter(j=>j.sentToSevlink===false):[]}
function reviewInboxMarkup(){const jobs=tenantReviewJobs();return `<div class="panel review-inbox" style="margin-top:22px"><div class="panelhead"><div><span class="eyebrow">${agencyNow().accountType==='landlord'?'OWNER APPROVAL':'PROPERTY MANAGER REVIEW'}</span><h2 style="margin-top:8px">Tenant reports to review <span class="badge">${jobs.length}</span></h2><p style="margin:5px 0">Complete the details, choose the service and send the job to Sevlink.</p></div></div>${jobs.map(j=>`<div class="listline toolbar"><div style="flex:1"><b>${esc(j.title)}</b><p>${esc(property(j.property)?.name)} · ${esc(state.tenants.find(t=>t.id===j.tenant)?.name)}<br>${j.ref} · ${date(j.createdAt)}</p></div><button class="primary" onclick="reviewTenantReportForm('${j.id}')">Review & send to Sevlink</button></div>`).join('')||'<p>No tenant reports waiting for review.</p>'}</div>`}
function reviewTenantReportForm(jid){const j=getJob(jid);if(role!=='manager'||!j||j.agency!==agency||j.sentToSevlink!==false)return;openForm('Review tenant report.',`<div class="notice"><b>${esc(property(j.property)?.name)}</b><p>${esc(j.title)}<br>${esc(j.description)}</p></div>${j.beforePhotos.length?`<div class="quote-photos">${j.beforePhotos.map(p=>`<img src="${p.data}" alt="Tenant repair photo">`).join('')}</div>`:''}<label>Job title</label><input name="title" required maxlength="180" value="${esc(j.title)}"><label>Details / work requested</label><textarea name="description" required rows="4" maxlength="3000">${esc(j.description)}</textarea><label>Service required</label><select name="service" id="reviewService"><option value="repair">Repair request / quote</option><option value="callout" ${j.clientServicePreference==='callout'?'selected':''}>Book a call-out</option></select><div id="reviewBudgetWrap" hidden><label>Maximum total call-out budget (ZAR)</label><input name="totalBudget" id="reviewBudget" type="number" min="0.01" max="10000000" step="0.01"><small>Only the agency authorises this total.</small></div><label>Priority</label><select name="priority"><option>Normal</option><option>High</option><option>Urgent</option></select>${accessChoiceFields(j)}<label>Access instructions for Sevlink (optional)</label><textarea name="access" rows="2" maxlength="1500"></textarea>`,'Send authorised request to Sevlink',async d=>{if(await dispatchTenantReport(jid,{title:d.get('title'),description:d.get('description'),service:d.get('service'),priority:d.get('priority'),totalBudget:Number(d.get('totalBudget')),access:d.get('access'),accessResponsibility:d.get('accessResponsibility')})){modal.close();render();toast('Reviewed job sent to Sevlink.')}});$('#reviewService').onchange=()=>{const callout=$('#reviewService').value==='callout';$('#reviewBudgetWrap').hidden=!callout;$('#reviewBudget').required=callout};$('#reviewService').onchange()}
async function dispatchTenantReport(jid,details){const j=getJob(jid);if(role!=='manager'||!j||j.agency!==agency||j.sentToSevlink!==false||!['repair','callout'].includes(details.service)||!['Normal','High','Urgent'].includes(details.priority)||!details.title?.trim()||!details.description?.trim())return false;if(details.service==='callout'&&(!Number.isFinite(details.totalBudget)||details.totalBudget<=0)){toast('Set the maximum total call-out budget before sending.');return false}return commit(()=>{j.title=details.title.trim();j.description=details.description.trim();j.priority=details.priority;j.sentToSevlink=true;j.dispatchStatus='Sent to Sevlink';j.dispatchedAt=now();j.dispatchedBy=person();j.clientInstructions=details.access||'';j.accessResponsibility=details.accessResponsibility||property(j.property)?.accessResponsibility||'sevlink';j.status='New';j.reviewedAt=null;j.opsAction=null;j.assigned=false;if(details.service==='callout')initialiseSimpleCallout(j,details.totalBudget,true);addEvent(j,'Property review completed','The '+clientOwner()+' reviewed the report and sent '+(details.service==='callout'?'an authorised call-out':'a repair / quote request')+' to Sevlink.');if(details.access)j.comments.push({author:person(),text:'Access instructions: '+details.access,visibility:'shared',at:now()});notify(j,'Reviewed request sent',j.ref+': ready for Sevlink action.')})}
const renderBeforeAuthority=render;render=function(){renderBeforeAuthority();if(!state)return;const landlord=agencyNow().accountType==='landlord';const roleOption=$('#role')?.querySelector('option[value="manager"]');if(roleOption)roleOption.textContent=landlord?'Landlord view':'Agency manager view';const profileButton=$('#nav').querySelector('[data-view="profile"]');if(profileButton)profileButton.textContent=landlord?'⚙  Landlord profile':'⚙  Agency profile';if($('#newAgency'))$('#newAgency').textContent='＋ Create agency profile';const agencyOption=$('#agencySwitch')?.querySelector('option[value="'+agency+'"]');if(agencyOption)agencyOption.textContent=agencyNow().name+(landlord?' · Landlord':' · Agency');if(role==='manager'&&['overview','requests'].includes(view))app.insertAdjacentHTML('afterbegin',reviewInboxMarkup());if(role==='tenant'&&view==='overview')app.insertAdjacentHTML('afterbegin',`<div class="banner"><b>Report a problem. Your ${clientOwner()} handles the rest.</b><br>You can add photos, follow updates and confirm access for an arranged visit. Job booking, budgets and approvals are managed by your ${clientOwner()}.</div>`);if(role==='manager'&&view==='profile'){app.insertAdjacentHTML('afterbegin',`<div class="banner"><b>${landlord?'Landlord account · own properties':'Property agency account'}</b><br>${landlord?'You review reports, authorise call-out budgets and approve quotes for your own properties.':'Your agency reviews tenant reports, adds job details and authorises work before sending to Sevlink.'}</div>`)}};
const detailBeforeAuthority=jobDetail;jobDetail=function(jid,section='comments'){detailBeforeAuthority(jid,section);const j=getJob(jid);if(!j)return;if(j.sentToSevlink===false){$('#jobcontent').insertAdjacentHTML('afterbegin',`<div class="notice"><b>Awaiting property manager review</b><p>This report has not been sent to Sevlink.</p>${role==='manager'?`<button class="primary" onclick="reviewTenantReportForm('${jid}')">Review details & send to Sevlink</button>`:''}</div>`);if(role==='manager'){$('#assign')?.remove();modal.querySelectorAll('[onclick*="authoriseCallout"],[onclick*="quoteForm"],[onclick*="bookingForm"]').forEach(b=>b.remove())}}if(role==='tenant')modal.querySelectorAll('[onclick*="scheduleForm"],[data-tab="quotes"],[data-tab="invoices"]').forEach(b=>b.remove())};
const scheduleBeforeAuthority=renderSchedule;renderSchedule=function(j){if(role==='tenant'){$('#jobcontent').innerHTML='<h2>Your appointment</h2>'+(j.schedule?.status==='Confirmed'?scheduleSummary(j):'<div class="notice">Your property agency will arrange the appointment with Sevlink. Confirmed details will appear here.</div>');return}return scheduleBeforeAuthority(j)};
const saveScheduleBeforeAuthority=saveSchedule;saveSchedule=async function(jid,...args){if(role==='tenant'){toast('Your property agency arranges appointments with Sevlink.');return false}return saveScheduleBeforeAuthority(jid,...args)};
agencyForm=function(create){const a=create?{}:agencyNow();openForm(create?'Create your account profile.':'Edit account profile.',`${create?'<label>I am signing up as</label><select name="accountType"><option value="agency">Property agency — manage client properties</option><option value="landlord">Landlord — manage my own properties</option></select>':'<div class="notice">'+(a.accountType==='landlord'?'Landlord account':'Property agency account')+'</div>'}${field('Agency name / landlord full name','name',a.name)}${field('Primary contact','contact',a.contact)}${field('Email','email',a.email,'email')}${field('Phone','phone',a.phone,'tel')}${field('Area','area',a.area)}<div class="notice">This creates a demo account workspace. Real sign-up, identity checks and invitation emails are not connected.</div>`,create?'Create demo profile':'Save profile',async d=>{const values=Object.fromEntries(d);if(create&&!['agency','landlord'].includes(values.accountType))return;if(await commit(()=>{if(create){const a={id:id('a'),...values};state.agencies.push(a);agency=a.id;tenant='';role='manager'}else Object.assign(agencyNow(),values)})){modal.close();navigate('profile');toast('Account profile saved.')}})};
const profileBeforeAuthority=renderProfile;renderProfile=function(){if(agencyNow().accountType!=='landlord')return profileBeforeAuthority();const a=agencyNow();app.innerHTML=heading('Your landlord profile.','Manage your own properties, tenant reports and maintenance approvals.','<button class="primary" onclick="agencyForm(false)">Edit profile</button>')+`<div class="card" style="max-width:750px"><span class="eyebrow">LANDLORD · OWN PROPERTY WORKSPACE</span><h1>${esc(a.name)}</h1><p>${esc(a.email)}<br>${esc(a.phone)}<br>${esc(a.area)}</p><div class="notice">${state.properties.filter(p=>canSeeProperty(p)).length} properties · ${state.tenants.filter(t=>t.agency===agency&&canSeeProperty(property(t.property))).length} tenants</div><h2>Your authority</h2><p>Add properties, invite tenants, review their reports, authorise call-out budgets, approve quotes and arrange appointments for your own properties.</p><button class="secondary" onclick="navigate('properties')">Manage my properties →</button></div>`};
const quotesBeforeAuthority=renderQuotes;renderQuotes=function(j){if(j.sentToSevlink===false){$('#jobcontent').innerHTML='<div class="notice">Review this tenant report and send the job to Sevlink before requesting a quote.</div>';return}return quotesBeforeAuthority(j)};
const approveCalloutBeforeAuthority=approveCallout;approveCallout=async function(jid,total){const j=getJob(jid);if(j?.sentToSevlink===false){toast('Review and send this report to Sevlink first.');return false}return approveCalloutBeforeAuthority(jid,total)};
const authoriseCalloutBeforeAuthority=authoriseCallout;authoriseCallout=function(jid){const j=getJob(jid);if(j?.sentToSevlink===false){reviewTenantReportForm(jid);return}return authoriseCalloutBeforeAuthority(jid)};
const extraDetailBeforeAuthority=jobDetail;jobDetail=function(jid,section='comments'){extraDetailBeforeAuthority(jid,section);const j=getJob(jid);if(j?.tenantReport)$('#jobcontent').insertAdjacentHTML('afterbegin',`<details class="notice"><summary>Original tenant report</summary><p><b>${esc(j.tenantReport.title)}</b><br>${esc(j.tenantReport.description)}</p></details>`);if(j&&role==='tenant'&&j.status!=='Completed')$('#jobcontent').insertAdjacentHTML('beforeend',`<div class="actions"><button class="secondary" onclick="addJobPhotoForm('${jid}')">Add another photo</button></div>`)};
